import{z as A,x as B,o as E,c as s,q as t,j as i,D as e,d as l,s as o,S as n}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"数据加载流水线","description":"","frontmatter":{"title":"数据加载流水线","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/dataloader-pipeline.md","filePath":"llm/dataloader-pipeline.md","lastUpdated":1791413859000}'),d={name:"llm/dataloader-pipeline.md"};function p(P,a,m,D,h,C){const r=B("Mermaid");return E(),s("div",null,[a[2]||(a[2]=t('<h1 id="数据加载流水线" tabindex="-1">数据加载流水线 <a class="header-anchor" href="#数据加载流水线" aria-label="Permalink to &quot;数据加载流水线&quot;">​</a></h1><div class="epigraph"><p>GPU 在等下一条 token 时，前面所有并行日历都是零；加载器要用预取、解压与切分的流水把磁盘延迟盖住。</p><footer>—— 对照 PyTorch DataLoader、WebDataset、Mosaic Streaming 等大规模流式加载实践</footer></div><p><a href="/llm/in-training-eval">上一课</a>要求评测不要接入训练预取队列。训练自己的队列若填不满，\\(b_{\\mathrm{micro}}\\) 再精、重叠再满，MFU 仍会周期性塌到零。本课不重讲探针。缺口是把「配比、α、仓库排布、FIM、长度上采样、去污染查询」收成一条不会成为落后者的加载流水。拓扑课将决定 GPU 怎么坐；本课决定 token 怎么流到坐着的 GPU。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>混合物不是一个随机可读的大数组。对象存储有尾延迟；解压、正则预分词、BPE、FIM 重排、SP padding 都在 CPU。多 rank 若打同一热文件，元数据服务器会先于 GPU 成为瓶颈。长文档上采样让长度方差变大，一个 rank 解 128k、另一个解 512，数据落后者出现。去污染查询若同步打远程指纹服务，每条样本加一次 RTT，灾难。<span class="marginnote">用数字感受一下：一次跨机房 RTT 按 1 毫秒算，一个 4096 条样本的微批就是约 4 秒的纯等待，而正常一步训练往往不到 1 秒——同步远程查询直接让数据管道慢 4 倍以上。所以指纹库必须整体拉到本地，查询走内存而不是网络。</span></p><p>加载器还要实现带权抽样与全局游标，以对接弹性与重放。PyTorch 默认 DataLoader 假设可 map 的本地数据集，万卡网页混合物通常要流式分片（WebDataset、Mosaic Streaming 一类）。</p><h3 id="cpu-切分必须与-gpu-词表一致" tabindex="-1">CPU 切分必须与 GPU 词表一致 <a class="header-anchor" href="#cpu-切分必须与-gpu-词表一致" aria-label="Permalink to &quot;CPU 切分必须与 GPU 词表一致&quot;">​</a></h3><p>预分词正则、特殊 token、数字切分，必须调用与推理相同的快照，不能用另一份 Python 正则「差不多」。fertility 报表若与加载器实际切分不一致，配比会计全错。</p><p><span class="marginnote">把 BPE 放在 GPU 上可以减 CPU，但异步检查点与重放仍要能在 CPU 上重切同一字节，得到同一 id。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>流水阶段：列出分片 → 按 \\(w\\) 与 α 抽文档 → 本地缓存指纹过滤 → 解码 → tokenizer → 可选 FIM / 打包填窗 → 按 SP 对齐 → pinned 内存预取多槽。<span class="marginnote">「pinned 内存」（锁页内存）就是被操作系统禁止换出到磁盘的内存：GPU 可以用 DMA 从这里直接搬数据，不用先经过一份临时的可分页拷贝。普通内存每次传输多一次拷贝和一次潜在的缺页等待，预取槽用它才能把延迟稳定地藏住。</span>槽深应盖住 P99 解压延迟，但受主机内存限制。超长样本提前切片，避免单 worker 卡死。每个 rank 只读自己的分片集合，shuffle 在分片内 + 跨 epoch 种子，全局游标存「分片 id + 文档偏移」。</p>',11)),(E(),i(n,null,{default:e(()=>[o(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E4%B8%8B%E4%B8%80%E5%BE%AE%E6%89%B9%E8%A2%AB%E8%AF%B7%E6%B1%82%22%5D%20--%3E%20B%7B%22%E9%98%9F%E5%88%97%E9%87%8C%E8%BF%98%E6%9C%89%E6%A7%BD%E5%90%97%EF%BC%9F%22%7D%0A%20%20B%20--%3E%7C%E6%9C%89%7C%20C%5B%22%E7%AB%8B%E5%8D%B3%E4%B8%8A%E5%8D%A1%EF%BC%8CCPU%20%E7%BB%A7%E7%BB%AD%E5%A1%AB%E6%A7%BD%22%5D%0A%20%20B%20--%3E%7C%E6%97%A0%7C%20D%5B%22GPU%20%E7%A9%BA%E8%BD%AC%E7%AD%89%E5%BE%85%E8%A7%A3%E5%8E%8B%22%5D%0A%20%20D%20--%3E%20E%5B%22%E9%98%9F%E5%88%97%E7%A9%BA%E8%AE%A1%E6%95%B0%20%2B1%22%5D%0A%20%20C%20--%3E%20F%7B%22%E6%A7%BD%E6%B7%B1%20%E2%89%A5%20P99%20%E8%A7%A3%E5%8E%8B%E5%BB%B6%E8%BF%9F%EF%BC%9F%22%7D%0A%20%20F%20--%3E%7C%E6%98%AF%7C%20C%0A%20%20F%20--%3E%7C%E5%90%A6%7C%20D%0A%20%20G%5B%22%E8%B6%85%E9%95%BF%E6%A0%B7%E6%9C%AC%20128k%20%E6%9C%AA%E5%88%87%E7%89%87%22%5D%20--%3E%20H%5B%22%E5%8D%95%20worker%20%E5%8D%A1%E4%BD%8F%22%5D%20--%3E%20D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p>去污染指纹库加载到本地或只读 mmap，禁止每条 RPC。评测作业用另一进程组与另一缓存。异步保存不要和加载器抢同一 NIC 到对象存储的带宽；可错峰或分盘。</p><h3 id="与累积、pp-的形状" tabindex="-1">与累积、PP 的形状 <a class="header-anchor" href="#与累积、pp-的形状" aria-label="Permalink to &quot;与累积、PP 的形状&quot;">​</a></h3><p>加载器一次吐 \\(b_{\\mathrm{micro}}\\)，流水 \\(M\\) 个微批需要 \\(M\\) 槽在飞。DualPipe 双流则接近 \\(2M\\)。槽数写进与并行计划同一张表，否则弹性换计划后预取深度错误，要么 OOM 要么饿死。</p><p><span class="marginnote">打包产生的 padding 应在日志里当无效 token 报。SP 对齐会加重 padding，有效吞吐不是 <code>tokens/sec</code> 字面。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>GPU 步时若大于加载 P99，流水把 IO 藏进计算，类似通信重叠。若加载 P99 更大，步时被数据管道的 \\(\\max\\) 决定，落后者课会把锅判给 GPU。正确分解是看「加载队列空」计数。<span class="marginnote">常见误区：看到吞吐下降就去调学习率或批大小，实际上第一步应该查「队列空」计数——若不为零，说明 GPU 在等磁盘，此时任何超参调整都是在优化一条不存在的瓶颈。配比 \\(w\\) 只有在队列非空时才真正被执行。</span>配比再好，队列空时 \\(w\\) 没有被执行，只是在执行磁盘。</p>',6)),(E(),i(n,null,{default:e(()=>[o(r,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20SHARD%5B%22%E5%88%86%E7%89%87%E5%88%97%E8%A1%A8%20%2B%20%E6%B8%B8%E6%A0%87%22%5D%20--%3E%20SMP%5B%22%E6%8C%89%20w%20%2F%20%CE%B1%20%E6%8A%BD%E6%A0%B7%22%5D%0A%20%20SMP%20--%3E%20FILT%5B%22%E6%9C%AC%E5%9C%B0%E5%8E%BB%E6%B1%A1%E6%9F%93%22%5D%0A%20%20FILT%20--%3E%20TOK%5B%22%E5%90%8C%E4%B8%80%E8%AF%8D%E8%A1%A8%E5%BF%AB%E7%85%A7%E5%88%87%E5%88%86%22%5D%0A%20%20TOK%20--%3E%20PACK%5B%22%E6%89%93%E5%8C%85%20%2F%20FIM%20%2F%20SP%20%E5%AF%B9%E9%BD%90%22%5D%0A%20%20PACK%20--%3E%20PRE%5B%22%E5%A4%9A%E6%A7%BD%E9%A2%84%E5%8F%96%22%5D%0A%20%20PRE%20--%3E%20GPU%5B%22%E5%BE%AE%E6%89%B9%E4%B8%8A%E5%8D%A1%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>加载流水不选择「哪些文档更有影响」——分数应离线算好写成权重表再抽样。也不放置 rank 到机架。下一课按网络拓扑把 DP/TP/PP/EP/SP 组放到 NVLink 与 IB 的正确切面上，否则加载再满，All-to-All 仍会在过订阅链路上变成落后者。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>本课不重讲评测隔离；只补训练 token 的 CPU/IO 流水。</li><li>切分必须用冻结词表快照；指纹本地化；超长先切片。</li><li>预取深度与 \\(M\\)、双流、弹性计划同表。</li><li>队列空计数是数据落后者的直接证据。</li><li>出处：WebDataset / Mosaic Streaming 流式加载；PyTorch DataLoader；与本课程词表及去污染约束对接。</li></ul>',4))])}const u=A(d,[["render",p]]);export{_ as __pageData,u as default};
